#!/usr/bin/env python3
"""Патч документации по итогам беседы L.2 (язык интерфейса es, испанский).

Беседа целиком (2026-11-26…27; пишется одним коммитом). Идемпотентный: каждая
правка проверяет наличие нового текста (marker) и уходит в skip при
повторном прогоне. Отчёт applied/skip/fail. Запуск из корня репозитория:
    python3 scripts/patches/patch-docs-convL2.py

  L2/A  NEXT-CONTEXT: снимок «Состояние» ПЕРЕПИСАН (L.2 закрыта; прежний —
        в 08 Часть V), сторож 4bv расширена, ближайшая по справке — L.3.
  L2/B  07: шаблон L — место UI_LOCALE_NAMES, общий харнесс тестовых
        запросов, 04/05 язык не дописывать, грабли L.2; указатель «По факту
        L.2»; строка L.2 справки кандидатов.
  L2/C  08: Часть I — абзац L.2; Часть II — глава «Беседа L.2» с тремя
        подразделами «По факту»; Часть V — снимок после L.1.
  L2/D  09: §4 — уроки L.2; §10 — «Что L.2 оставила знать».
  L2/E  04/05: языки интерфейса — ссылкой на UI_LOCALES, каталоги <xx>.json;
        test-L-requests.
  L2/F  README — строка типовой беседы L; scripts/i18n/README — es
        утверждён; chrome/README — кэш 131 первым, CHROME_PATH запасной.
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent
PNC = ROOT / "NEXT-CONTEXT.md"
P07 = ROOT / "docs/07-conversation-protocol.md"
P08 = ROOT / "docs/08-history.md"
P09 = ROOT / "docs/09-lessons.md"
P04 = ROOT / "docs/04-code-reuse-map.md"
P05 = ROOT / "docs/05-file-structure.md"
PRM = ROOT / "README.md"
PI18N = ROOT / "scripts/i18n/README.md"
PCH = ROOT / "chrome/README.md"

applied = 0
skipped = 0
failed = 0


def patch(path: Path, old: str, new: str, label: str, marker: str | None = None) -> None:
    """Заменяет old → new; идемпотентность — по marker (или new) в тексте."""
    global applied, skipped, failed
    text = path.read_text(encoding="utf-8")
    probe = marker if marker is not None else new
    if probe in text:
        print(f"  skip  {label}")
        skipped += 1
        return
    if text.count(old) != 1:
        print(f"  FAIL  {label}: якорь встречается {text.count(old)} раз")
        failed += 1
        return
    path.write_text(text.replace(old, new), encoding="utf-8")
    print(f"  ok    {label}")
    applied += 1


